"""Exercise the parser against the CSV actually generated by the ARM C test."""
import importlib.util
from pathlib import Path
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]


def module(name, file):
    spec = importlib.util.spec_from_file_location(name, ROOT / 'scripts' / file)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


parser = module('blackbox_reader', 'read-blackbox.py')
layout = module('firmware_layout', 'check-firmware-layout.py')


def record(kind, address, data=b''):
    raw = bytes([len(data), address >> 8, address & 255, kind]) + data
    return ':' + (raw + bytes([-sum(raw) & 255])).hex() + '\n'


class LogToolsTests(unittest.TestCase):
    def setUp(self):
        self.text = (ROOT / 'build/control-tests/blackbox-export.csv').read_text()

    def test_c_output_with_hercules_surrounding_text(self):
        log = parser.parse_log('Serial port open\n' + self.text + '\nPort closed\n')
        self.assertEqual(log['firmware'], 'B34')
        self.assertEqual(log['profile']['kd_x1000'], 120)
        self.assertEqual(log['rows'][-1]['mode'], 0)
        self.assertTrue(log['rows'][-1]['flags'] & 4)
        self.assertEqual(parser.summarize(log)['sample_count'], len(log['rows']))

    def test_truncation_rejected(self):
        with self.assertRaisesRegex(ValueError, 'Incomplete'):
            parser.parse_log(self.text.split('# END')[0])

    def test_changed_digit_rejected(self):
        with self.assertRaisesRegex(ValueError, 'CRC32'):
            parser.parse_log(self.text.replace('12000', '12001', 1))

    def test_missing_sample_rejected(self):
        lines = self.text.splitlines()
        del lines[10]
        with self.assertRaisesRegex(ValueError, 'CRC32'):
            parser.parse_log('\n'.join(lines))

    def test_concatenated_runs_rejected(self):
        with self.assertRaisesRegex(ValueError, 'exactly one'):
            parser.parse_log(self.text + self.text)

    def test_newline_conversion_supported(self):
        self.assertEqual(parser.parse_log(self.text)['crc32'],
                         parser.parse_log(self.text.replace('\n', '\r\n'))['crc32'])

    def test_end_count_mismatch_rejected(self):
        end = self.text.index('# END,count,')
        broken = self.text[:end] + self.text[end:].replace('count,', 'count,9', 1)
        with self.assertRaises(ValueError):
            parser.parse_log(broken)

    def test_layout_boundary_and_checksum(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / 'test.hex'
            upper = record(4, 0, b'\x08\x00')
            path.write_text(upper + record(0, 0xBFFE, b'\x01\x02') + record(1, 0))
            self.assertEqual(layout.check(path), 0x0800C000)
            path.write_text(upper + record(0, 0xBFFF, b'\x01\x02') + record(1, 0))
            with self.assertRaisesRegex(ValueError, 'overlaps'):
                layout.check(path)
            path.write_text(upper + ':02BFFE00010200\n' + record(1, 0))
            with self.assertRaisesRegex(ValueError, 'checksum'):
                layout.check(path)


if __name__ == '__main__':
    unittest.main()
